const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.log_id) {
    node.error("Rayvn ikke konfigurert på denne tilkoblingen");
    return null;
}

msg.url = global.get("parat_bridge").base_urls.rayvn
    + "/logs/" + target.client_specific.log_id + "/entry";

msg.headers = {
    "Authorization": "Bearer " + target.api_key,
    "Content-Type":  "application/json",
    "Accept":        "application/json"
};

return msg;

msg.topic = "response";

if (msg.statusCode === 200) {
    msg.result = true;
} else {
    msg.result = false;
}

return msg;

/**
 * Fires a sender notification about attachment failures after a successful POST.
 *
 * Reads metadata.failed_files — complete picture including upload failures.
 * Only sends notification if POST succeeded; on failure the queue handles
 * retry and notification.
 *
 * Output 1: msg continues (always)
 * Output 2: notification payload to the attachment notification handler
 */
if (msg.result !== true) return [msg, null];

const failed = msg.metadata.failed_files || [];
if (failed.length === 0) return [msg, null];

const notification = {
    payload: {
        entry_id:     msg.entry.id,
        failed_files: failed,
        entry_author: msg.entry.author,
        metadata:     msg.metadata
    }
};

return [msg, notification];
